function slotInsert(slots, newSlot) {
  const all = [...slots, newSlot].map(([s, e]) => [s, e]).sort((a, b) => a[0] - b[0]);
  const merged = [];
  for (const [s, e] of all) {
    const last = merged[merged.length - 1];
    if (last && s <= last[1]) last[1] = Math.max(last[1], e);
    else merged.push([s, e]);
  }
  return merged;
}

function slotInsert(slots, newSlot) {
  const result = [];
  let [start, end] = newSlot;
  let i = 0;
  while (i < slots.length && slots[i][1] < start) { result.push([slots[i][0], slots[i][1]]); i++; }
  while (i < slots.length && slots[i][0] <= end) {
    start = Math.min(start, slots[i][0]);
    end = Math.max(end, slots[i][1]);
    i++;
  }
  result.push([start, end]);
  while (i < slots.length) { result.push([slots[i][0], slots[i][1]]); i++; }
  return result;
}
